+.main{margin-left:var(--sidebar-w);flex:1;padding:24px 28px;padding-bottom:calc(var(--tab-h) + 20px);max-width:900px}
+.tab-panel{display:none;animation:fadeIn 0.25s ease}
+.tab-panel.active{display:block}
+
+/* ========== Mobile Tabs ========== */
+.mobile-tabs{display:none;position:fixed;bottom:0;left:0;right:0;background:var(--card);border-top:1px solid var(--border);z-index:100;padding:6px 8px;padding-bottom:calc(6px + env(safe-area-inset-bottom, 0px))}
+.mobile-tabs .tab-item{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;padding:6px 4px;border-radius:10px;color:var(--text-light);font-size:11px;font-weight:500;transition:all 0.2s;min-height:48px}
+.mobile-tabs .tab-item.active{color:var(--mint);font-weight:600}
+.mobile-tabs .tab-item svg{width:22px;height:22px}
+
+/* ========== Cards ========== */
+.card{background:var(--card);border-radius:var(--radius);padding:20px;box-shadow:var(--shadow);margin-bottom:16px;border:1px solid var(--border)}
+.card-header{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px}
+.card-title{font-size:15px;font-weight:700;color:var(--text);display:flex;align-items:center;gap:8px}
+.card-subtitle{font-size:12px;color:var(--text-light);margin-top:2px}
+.stats-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:12px}
+.stat-item{background:var(--cream);border-radius:var(--radius-sm);padding:14px;text-align:center}
+.stat-item .stat-value{font-size:22px;font-weight:700;color:var(--text)}
+.stat-item .stat-value.income{color:var(--income)}
+.stat-item .stat-value.expense{color:var(--expense)}
+.stat-item .stat-label{font-size:12px;color:var(--text-secondary);margin-top:4px}
+
+/* ========== Today Section ========== */
+.today-section{background:linear-gradient(135deg,#fef9f0,#fff5ee);border:1.5px solid var(--peach);border-radius:var(--radius);padding:18px 20px;margin-bottom:20px}
+.today-section .today-title{font-size:14px;font-weight:700;color:var(--peach);display:flex;align-items:center;gap:8px;margin-bottom:10px}
+.today-item{display:flex;align-items:center;justify-content:space-between;padding:8px 0;font-size:13px}
+.today-item+.today-item{border-top:1px solid var(--peach-light)}
+.today-item .today-badge{padding:2px 8px;border-radius:20px;font-size:11px;font-weight:600}
+.today-badge.urgent{background:#fde8e8;color:var(--danger)}
+.today-badge.normal{background:var(--mint-pale);color:var(--mint)}
+.today-item .today-action{font-size:12px;color:var(--mint);font-weight:600;text-decoration:underline;cursor:pointer}
+
+/* ========== Hourly Wage Card ========== */
+.hourly-card .big-number{font-size:42px;font-weight:800;color:var(--mint);line-height:1.2}
