+<script>
+// ============================================================
+//  打工人小账本 — 数据层 & 业务逻辑
+// ============================================================
+
+const STORAGE = {
+  HOURLY: 'wb_ledger_hourly',
+  RECORDS: 'wb_ledger_records',
+  GOALS: 'wb_ledger_goals',
+  SAFETY: 'wb_ledger_safety',
+  SETTINGS: 'wb_ledger_settings'
+};
+
+const CATEGORIES = {
+  expense: ['餐饮','交通','房租','水电','购物','娱乐','学习','医疗','通讯','服饰','居家','其他'],
+  income: ['工资','奖金','理财','兼职','红包','报销','其他收入']
+};
+
+const TODAY = new Date();
+const YM = TODAY.getFullYear()+'-'+String(TODAY.getMonth()+1).padStart(2,'0');
+
+// ========== Data Load/Save ==========
+function load(key, fallback) {
+  try { const v = localStorage.getItem(key); return v ? JSON.parse(v) : fallback; }
+  catch(e) { return fallback; }
+}
+function save(key, data) { localStorage.setItem(key, JSON.stringify(data)); }
+
+function getHourlySettings() {
+  return load(STORAGE.HOURLY, {
+    monthlySalary: 8000, payMonths: 12, annualCost: 5000,
+    dailyHours: 10, commuteMinutes: 60, workDaysPerMonth: 22,
+    annualOvertime: 100
+  });
+}
+
+function getRecords() { return load(STORAGE.RECORDS, []); }
+function getGoals() { return load(STORAGE.GOALS, { target: 500000, current: 150000, monthlyPlan: 5000 }); }
+function getSafety() { return load(STORAGE.SAFETY, { target: 60000, current: 20000 }); }
+function getSettings() { return load(STORAGE.SETTINGS, { initialized: false }); }
+
+// ========== Demo Data Generation ==========
+function generateDemoData() {
+  const settings = getSettings();
+  if (settings.initialized) return;
+  const now = new Date();
+  const demoRecords = [
+    { id: Date.now()-86400000*1, type:'expense', amount:35.5, category:'餐饮', note:'午餐外卖', date:fmtDate(new Date(now-86400000*1)), timestamp:now.getTime()-86400000*1, workMinutes:0, isSample:true },
+    { id: Date.now()-86400000*2, type:'expense', amount:128, category:'购物', note:'超市采购', date:fmtDate(new Date(now-86400000*2)), timestamp:now.getTime()-86400000*2, workMinutes:0, isSample:true },
+    { id: Date.now()-86400000*3, type:'income', amount:8000, category:'工资', note:'7月工资', date:fmtDate(new Date(now-86400000*3)), timestamp:now.getTime()-86400000*3, workMinutes:0, isSample:true },
+    { id: Date.now()-86400000*5, type:'expense', amount:2500, category:'房租', note:'8月房租', date:fmtDate(new Date(now-86400000*5)), timestamp:now.getTime()-86400000*5, workMinutes:0, isSample:true },
+    { id: Date.now()-86400000*35, type:'expense', amount:89, category:'交通', note:'加油', date:fmtDate(new Date(now-86400000*35)), timestamp:now.getTime()-86400000*35, workMinutes:0, isSample:true }
+  ];
+  // Calculate work minutes for each demo record
+  const hw = getHourlySettings();
+  const hwRate = calcHourlyWage(hw).rate;
+  demoRecords.forEach(r => { r.workMinutes = Math.round(r.amount / hwRate * 60); });
+  save(STORAGE.RECORDS, demoRecords);
+  save(STORAGE.SETTINGS, { initialized: true });
+}
+
+function fmtDate(d) {
+  return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
+}
+
+// ========== Hourly Wage Calculation ==========
+function calcHourlyWage(hw) {
+  const annualIncome = hw.monthlySalary * hw.payMonths - hw.annualCost;
+  const commuteHoursPerDay = hw.commuteMinutes / 60;
+  const totalDailyHours = hw.dailyHours + commuteHoursPerDay;
+  const annualWorkHours = totalDailyHours * hw.workDaysPerMonth * 12 + hw.annualOvertime;
+  const rate = annualWorkHours > 0 ? annualIncome / annualWorkHours : 0;
+  return { annualIncome, annualWorkHours, rate, totalDailyHours };
+}
+
+function calcWorkMinutes(amount, hourlyRate) {
+  if (hourlyRate <= 0) return 0;
+  return Math.round(amount / hourlyRate * 60);
+}
+
+// ========== Record Management ==========
+function addRecord() {
+  const amountEl = document.getElementById('recordAmount');
+  const amount = parseFloat(amountEl.value);
+  if (isNaN(amount) || amount <= 0) { showToast('请输入有效金额', 'error'); return; }
+  const type = document.getElementById('typeExpense').classList.contains('expense-active') ? 'expense' : 'income';
+  const category = document.getElementById('recordCategory').value;
+  const note = document.getElementById('recordNote').value.trim();
+  const now = new Date();
+  const hw = calcHourlyWage(getHourlySettings());
+  const workMinutes = calcWorkMinutes(amount, hw.rate);
+  const record = {
+    id: Date.now(), type, amount, category, note,
+    date: fmtDate(now), timestamp: now.getTime(), workMinutes, isSample: false
+  };
+  const records = getRecords();
+  records.unshift(record);
+  save(STORAGE.RECORDS, records);
+  // Show result
+  const resultEl = document.getElementById('quickResult');
+  const sym = type === 'expense' ? '支出' : '收入';
+  const eq = type === 'expense' ? '相当于工作了' : '相当于赚了';
+  resultEl.innerHTML = '<b>'+sym+' ¥'+amount.toFixed(2)+'</b> — '+eq+' <b>'+workMinutes+' 分钟</b>（时薪 ¥'+hw.rate.toFixed(2)+'）';
+  resultEl.classList.add('show');
+  setTimeout(() => resultEl.classList.remove('show'), 5000);
+  amountEl.value = '';
+  document.getElementById('recordNote').value = '';
+  amountEl.focus();
+  refreshAll();
+}
+
+// ========== Filtering ==========
+function getFilteredRecords() {
+  const records = getRecords();
+  const filter = document.getElementById('recordFilter') ? document.getElementById('recordFilter').value : 'all';
+  if (filter === 'expense') return records.filter(r => r.type === 'expense');
+  if (filter === 'income') return records.filter(r => r.type === 'income');
+  if (filter === 'month') return records.filter(r => r.date.startsWith(YM));
+  return records;
+}
+
+function getMonthlyStats() {
+  const records = getRecords().filter(r => r.date.startsWith(YM));
+  let income = 0, expense = 0;
+  records.forEach(r => { if (r.type === 'income') income += r.amount; else expense += r.amount; });
+  return { income, expense, balance: income - expense };
+}
+
+function getRecent3MonthAvgExpense() {
+  const now = new Date();
+  let total = 0, months = 0;
+  for (let i = 0; i < 3; i++) {
+    const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
+    const ym = d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');
+    const records = getRecords().filter(r => r.date.startsWith(ym) && r.type === 'expense');
+    if (records.length > 0) {
+      total += records.reduce((s, r) => s + r.amount, 0);
+      months++;
+    }
+  }
+  return months > 0 ? total / months : 3000;
+}
+
+// ========== Savings Curve Data ==========
+function getSavingsData() {
+  const records = getRecords().sort((a, b) => a.timestamp - b.timestamp);
+  const monthly = {};
+  records.forEach(r => {
+    const ym = r.date.substring(0, 7);
+    if (!monthly[ym]) monthly[ym] = 0;
+    monthly[ym] += r.type === 'income' ? r.amount : -r.amount;
+  });
+  const sorted = Object.keys(monthly).sort();
+  let cumulative = 0;
+  return sorted.map(ym => { cumulative += monthly[ym]; return { month: ym, net: monthly[ym], cumulative }; });
+}
