+function renderSavingsChart() {
+  const data = getSavingsData();
+  const container = document.getElementById('savingsChart');
+  if (data.length < 2) {
+    container.innerHTML = '<div class="text-center" style="padding:30px;color:var(--text-light)">数据不足，需要至少两个月的记录才能绘制曲线</div>';
+    return;
+  }
+  const W = Math.max(500, data.length * 70);
+  const H = 200; const pad = { top: 20, right: 30, bottom: 30, left: 60 };
+  const vals = data.map(d => d.cumulative);
+  const min = Math.min(0, ...vals);
+  const max = Math.max(...vals, 1);
+  const range = max - min || 1;
+  const xScale = (W - pad.left - pad.right) / (data.length - 1 || 1);
+  const yScale = (H - pad.top - pad.bottom) / range;
+  const x = i => pad.left + i * xScale;
+  const y = v => pad.top + (H - pad.top - pad.bottom) - (v - min) * yScale;
+
+  // Grid lines
+  let gridLines = '';
+  const gridCount = 4;
+  for (let i = 0; i <= gridCount; i++) {
+    const val = min + range * i / gridCount;
+    const yy = y(val);
+    gridLines += '<line x1="'+pad.left+'" y1="'+yy+'" x2="'+(W-pad.right)+'" y2="'+yy+'" stroke="#f0e8d8" stroke-width="1"/><text x="'+(pad.left-6)+'" y="'+(yy+4)+'" text-anchor="end" font-size="10" fill="#b8a898">¥'+(val/10000).toFixed(1)+'w</text>';
+  }
+
+  // Line path
+  let pathD = '';
+  data.forEach((d, i) => { pathD += (i===0?'M':'L') + x(i)+','+y(d.cumulative)+' '; });
+
+  // Area path
+  let areaD = pathD + ' L'+x(data.length-1)+','+y(min)+' L'+x(0)+','+y(min)+' Z';
+
+  // Points
+  let points = '';
+  data.forEach((d, i) => {
+    points += '<circle cx="'+x(i)+'" cy="'+y(d.cumulative)+'" r="3.5" fill="var(--mint)" stroke="#fff" stroke-width="1.5"/>';
+    if (i % Math.max(1, Math.floor(data.length/6)) === 0 || i === data.length-1) {
+      points += '<text x="'+x(i)+'" y="'+(H-pad.bottom+14)+'" text-anchor="middle" font-size="10" fill="#9a8c7e">'+d.month.substring(5)+'月</text>';
+    }
+  });
+
+  // Zero line
+  const zeroY = y(0);
+  if (min < 0) {
+    gridLines += '<line x1="'+pad.left+'" y1="'+zeroY+'" x2="'+(W-pad.right)+'" y2="'+zeroY+'" stroke="#e0d0c0" stroke-width="1" stroke-dasharray="4,4"/>';
+  }
+
+  container.innerHTML = '<svg viewBox="0 0 '+W+' '+H+'" width="'+W+'" height="'+H+'" style="display:block;margin:0 auto">'+
+    gridLines+
+    '<path d="'+areaD+'" fill="var(--mint-pale)" opacity="0.5"/>'+
+    '<path d="'+pathD+'" fill="none" stroke="var(--mint)" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round"/>'+
+    points+
+  '</svg>';
+}
